import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type DroneMarketGrowthProps = Record<string, any>;

// Simple SVG Drone component
const StylizedDrone: React.FC<{ progress: number; hoverOffset: number; accentColor: string }> = ({
  progress,
  hoverOffset,
  accentColor,
}) => {
  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        transform: `translate(${progress}px, ${hoverOffset}px)`,
        width: 300,
        height: 200,
        zIndex: 10,
        transition: "none",
      }}
    >
      <svg width="100%" height="100%" viewBox="0 0 300 200" fill="none">
        {/* Props back - White */}
        <rect x="30" y="40" width="80" height="6" rx="3" fill="#FFFFFF" />
        <rect x="190" y="40" width="80" height="6" rx="3" fill="#FFFFFF" />
        
        {/* Arms */}
        <path d="M100 85 L70 50" stroke="#CBD5E1" strokeWidth="8" strokeLinecap="round" />
        <path d="M200 85 L230 50" stroke="#CBD5E1" strokeWidth="8" strokeLinecap="round" />
        
        {/* Motors */}
        <rect x="60" y="46" width="20" height="15" rx="2" fill="#E2E8F0" />
        <rect x="220" y="46" width="20" height="15" rx="2" fill="#E2E8F0" />
        
        {/* Tactical Accents on arms (Matched to accentColor) */}
        <rect x="85" y="70" width="10" height="6" fill={accentColor} transform="rotate(-45 85 70)" />
        <rect x="205" y="70" width="10" height="6" fill={accentColor} transform="rotate(45 205 70)" />

        {/* Body - White/Light Grey */}
        <ellipse cx="150" cy="85" rx="60" ry="25" fill="#FFFFFF" />
        <path d="M100 85 Q150 110 200 85 Z" fill="#E2E8F0" />
        
        {/* Landing Gear */}
        <path d="M130 100 Q110 140 110 170" stroke="#CBD5E1" strokeWidth="6" strokeLinecap="round" fill="none" />
        <path d="M170 100 Q190 140 190 170" stroke="#CBD5E1" strokeWidth="6" strokeLinecap="round" fill="none" />
        
        {/* Camera Gimbal & Camera */}
        <rect x="145" y="110" width="10" height="15" fill="#94A3B8" />
        <rect x="130" y="125" width="40" height="30" rx="4" fill="#F1F5F9" />
        <circle cx="150" cy="140" r="10" fill="#0F172A" />
        {/* Tactical Red Eye Lens Flare */}
        <circle cx="150" cy="140" r="4" fill="#FF0000" />
      </svg>
    </div>
  );
};

const DroneMarketGrowth: React.FC<DroneMarketGrowthProps> = ({
  backgroundColor = "#0A1A2F",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "Commercial Drones are Taking Off",
  subtitle = "Projected worldwide market growth for commercial drones",
  barColor = "#00E5FF",
  bubbleColor = "#0D223F",
  data = [
    { year: "2016", dronesSold: 110, revenue: 0.6 },
    { year: "2017", dronesSold: 159, revenue: 0.8 },
    { year: "2018", dronesSold: 246, revenue: 1.1 },
    { year: "2019", dronesSold: 392, revenue: 1.6 },
    { year: "2020", dronesSold: 634, revenue: 2.4 },
    { year: "2021", dronesSold: 996, revenue: 3.6 },
    { year: "2022", dronesSold: 1414, revenue: 5.3 },
    { year: "2023", dronesSold: 1909, revenue: 7.6 },
    { year: "2024", dronesSold: 2329, revenue: 10.1 },
    { year: "2025", dronesSold: 2679, revenue: 12.6 },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Title Animations
  const titleOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [0, 15], [20, 0], {
    extrapolateRight: "clamp",
  });

  const subtitleOpacity = interpolate(frame, [5, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  const subtitleY = interpolate(frame, [5, 20], [20, 0], {
    extrapolateRight: "clamp",
  });

  const legendOpacity = interpolate(frame, [15, 30], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Chart Dimensions & Scales
  const chartWidth = width * 0.8;
  const chartHeight = height * 0.35; // Reduced from 0.45 to prevent overlap with bubbles
  const maxDrones = Math.max(...data.map((d) => d.dronesSold));
  const maxRevenue = Math.max(...data.map((d) => d.revenue));

  // Bubble dimensions
  const bubbleBaseRadius = 20;
  const bubbleMaxExtraRadius = 40;
  const maxBubbleDiameter = (bubbleBaseRadius + bubbleMaxExtraRadius) * 2;

  // Drone Animation
  const droneStartX = -300;
  const droneEndX = width * 0.15;
  const droneProgress = interpolate(frame, [20, 90], [droneStartX, droneEndX], {
    extrapolateRight: "clamp",
  });
  // Add a hovering bobbing effect
  const droneHover = Math.sin(frame / 8) * 15;
  // Centered vertically (adjusted for 200px drone height)
  const droneBaseY = (height / 2) - 100;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: robotoMonoFamily,
        color: "#E5E7EB",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        paddingBottom: height * 0.05, // Moves the centered content slightly higher
        position: "relative",
      }}
    >
      {/* Graph Paper Background */}
      {!transparentBackground && (
        <svg
          width="100%"
          height="100%"
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            zIndex: 0,
          }}
        >
          <defs>
            <pattern
              id="smallGrid"
              width="20"
              height="20"
              patternUnits="userSpaceOnUse"
            >
              <path
                d="M 20 0 L 0 0 0 20"
                fill="none"
                stroke={barColor}
                strokeOpacity="0.1"
                strokeWidth="0.5"
              />
            </pattern>
            <pattern
              id="largeGrid"
              width="100"
              height="100"
              patternUnits="userSpaceOnUse"
            >
              <rect width="100" height="100" fill="url(#smallGrid)" />
              <path
                d="M 100 0 L 0 0 0 100"
                fill="none"
                stroke={barColor}
                strokeOpacity="0.25"
                strokeWidth="1"
              />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#largeGrid)" />
        </svg>
      )}

      {/* Header Area */}
      <div
        style={{
          width: chartWidth,
          display: "flex",
          flexDirection: "column",
          gap: "10px",
          marginBottom: height * 0.04,
          zIndex: 1,
        }}
      >
        <h1
          style={{
            fontSize: 54,
            fontWeight: 800,
            margin: 0,
            color: "#FFFFFF",
            textTransform: "uppercase",
            letterSpacing: "2px",
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            transition: "none",
          }}
        >
          {title}
        </h1>
        <p
          style={{
            fontSize: 32,
            fontWeight: 400,
            margin: 0,
            color: barColor,
            opacity: subtitleOpacity * 0.9,
            transform: `translateY(${subtitleY}px)`,
            transition: "none",
          }}
        >
          {subtitle}
        </p>

        {/* Legend */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            gap: "40px",
            marginTop: "20px",
            justifyContent: "center",
            opacity: legendOpacity,
            transition: "none",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <div
              style={{
                width: 24,
                height: 24,
                borderRadius: "50%",
                backgroundColor: bubbleColor,
                border: `2px solid ${barColor}`,
                boxShadow: `0 0 8px ${barColor}`,
              }}
            />
            <span style={{ fontSize: 24, color: "#CBD5E1" }}>
              Revenue (in billion U.S. dollars)
            </span>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <div
              style={{
                width: 24,
                height: 24,
                backgroundColor: barColor,
                borderRadius: 4,
                boxShadow: `0 0 8px ${barColor}`,
              }}
            />
            <span style={{ fontSize: 24, color: "#CBD5E1" }}>
              Drones sold (in thousands)
            </span>
          </div>
        </div>
      </div>

      {/* Decorative Drone */}
      <StylizedDrone 
        progress={droneProgress} 
        hoverOffset={droneBaseY + droneHover} 
        accentColor={barColor}
      />

      {/* Main Chart Area */}
      <div
        style={{
          width: chartWidth,
          height: height * 0.65, // Explicit height to enable predictable vertical centering
          display: "flex",
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "flex-end",
          position: "relative",
          paddingBottom: "80px", // Space for X-axis labels
          boxSizing: "border-box",
          zIndex: 1,
        }}
      >
        {/* Baseline Line */}
        <div
          style={{
            position: "absolute",
            bottom: "80px",
            left: "-2%",
            right: "-2%",
            height: "2px",
            backgroundColor: "rgba(255, 255, 255, 0.2)",
            opacity: legendOpacity, // tie to legend fade
            transition: "none",
          }}
        />

        {data.map((item, index) => {
          // Animation timings staggered by index
          const startFrame = 30 + index * 5;
          
          const barScaleY = spring({
            frame: frame - startFrame,
            fps,
            config: { damping: 14, stiffness: 100 },
          });

          const bubbleScale = spring({
            frame: frame - (startFrame + 10),
            fps,
            config: { damping: 12, stiffness: 120 },
          });

          const labelOpacity = interpolate(
            frame,
            [startFrame + 5, startFrame + 15],
            [0, 1],
            { extrapolateRight: "clamp" }
          );

          // Calculations
          const barHeight = (item.dronesSold / maxDrones) * chartHeight;
          const bubbleRadius =
            bubbleBaseRadius + (item.revenue / maxRevenue) * bubbleMaxExtraRadius;

          return (
            <div
              key={item.year}
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                width: `${100 / data.length}%`,
                position: "relative",
                height: "100%",
                justifyContent: "flex-end",
                transition: "none",
              }}
            >
              {/* Revenue Bubble & Label (positioned at top) */}
              <div
                style={{
                  position: "absolute",
                  top: 0, // Position safely aligned to top of chart bounds avoiding header text overlap
                  height: maxBubbleDiameter, // Enforce fixed height to align all circles' centers vertically
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  width: "100%",
                  transition: "none",
                }}
              >
                <div
                  style={{
                    width: bubbleRadius * 2,
                    height: bubbleRadius * 2,
                    borderRadius: "50%",
                    backgroundColor: bubbleColor,
                    border: `2px solid ${barColor}`,
                    boxShadow: `0 0 10px ${barColor}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    transform: `scale(${bubbleScale})`,
                    transition: "none",
                  }}
                >
                  <span
                    style={{
                      fontSize: bubbleRadius * 0.6,
                      fontWeight: 600,
                      color: "#FFFFFF",
                      opacity: labelOpacity,
                      transition: "none",
                    }}
                  >
                    {item.revenue.toFixed(1)}
                  </span>
                </div>
              </div>

              {/* Drones Sold Bar Label */}
              <div
                style={{
                  marginBottom: "10px",
                  fontSize: 24,
                  fontWeight: 500,
                  color: "#FFFFFF",
                  opacity: labelOpacity,
                  transform: `translateY(${interpolate(
                    barScaleY,
                    [0, 1],
                    [20, 0]
                  )}px)`,
                  transition: "none",
                }}
              >
                {item.dronesSold.toLocaleString()}
              </div>

              {/* Drones Sold Bar */}
              <div
                style={{
                  width: "60%",
                  height: barHeight,
                  backgroundColor: barColor,
                  boxShadow: `0 0 15px ${barColor}`,
                  transformOrigin: "bottom center",
                  transform: `scaleY(${Math.max(0, barScaleY)})`, // prevent negative scale
                  transition: "none",
                }}
              />

              {/* X-Axis Year Label */}
              <div
                style={{
                  position: "absolute",
                  bottom: "-50px",
                  fontSize: 24,
                  fontWeight: 500,
                  color: "#CBD5E1",
                  opacity: interpolate(frame, [15, 30], [0, 1], {
                    extrapolateRight: "clamp",
                  }),
                  transition: "none",
                }}
              >
                {item.year}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default DroneMarketGrowth;